WITH filtered_accounts AS (SELECT *, ROUND(balance * 0.9, 2) AS balance_scaled FROM accounts WHERE balance < 71000 AND customer_id IN (1, 33, 40) AND status = 'CLOSED'), AccountsStats AS (SELECT status, MAX(opened_date) AS last_opened_date, SUM(CASE WHEN account_type = 'CHECKING' THEN balance ELSE 0 END) AS checking_balance FROM filtered_accounts GROUP BY status) SELECT * FROM AccountsStats
